select * from (select is_active, case when year(signup_date) < 2024 then 'before_2024' when year(signup_date) = 2024 then '2024' else 'after_2024' end as signup_cohort, concat_ws(', ', sort_array(collect_set(city))) as city_values, count(age) as age_count from customers where country = 'US' group by is_active, case when year(signup_date) < 2024 then 'before_2024' when year(signup_date) = 2024 then '2024' else 'after_2024' end) as t where age_count >= 8
